-- =====================================================
-- TABEL: site_settings
-- Fungsi: Pengaturan umum website (nama, logo, warna, dll)
-- =====================================================
CREATE TABLE IF NOT EXISTS site_settings (  
    id INT AUTO_INCREMENT PRIMARY KEY,
    setting_key VARCHAR(100) NOT NULL UNIQUE COMMENT 'Kunci pengaturan (unik)',
    setting_value TEXT COMMENT 'Nilai pengaturan',
    setting_type ENUM('text', 'textarea', 'image', 'color', 'url', 'number') DEFAULT 'text' COMMENT 'Tipe input',
    setting_group VARCHAR(50) DEFAULT 'general' COMMENT 'Grup pengaturan (general, hero, footer, dll)',
    setting_label VARCHAR(100) COMMENT 'Label tampilan di admin',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Pengaturan umum website';

