-- =====================================================
-- TABEL: navigation_menu
-- Fungsi: Menu navigasi website (bisa ditambah/edit/hapus)
-- =====================================================
CREATE TABLE IF NOT EXISTS navigation_menu (
    id INT AUTO_INCREMENT PRIMARY KEY,
    menu_label VARCHAR(100) NOT NULL COMMENT 'Nama menu yang ditampilkan',
    menu_link VARCHAR(255) NOT NULL COMMENT 'Link tujuan menu',
    menu_order INT DEFAULT 0 COMMENT 'Urutan tampilan menu',
    is_button TINYINT(1) DEFAULT 0 COMMENT '1 = tampil sebagai button, 0 = tampil sebagai link biasa',
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = nonaktif',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Menu navigasi website';

