-- =====================================================
-- TABEL: features
-- Fungsi: Section "Mengapa Memilih Kami" (feature cards)
-- =====================================================
CREATE TABLE IF NOT EXISTS features (
    id INT AUTO_INCREMENT PRIMARY KEY,
    icon VARCHAR(100) NOT NULL COMMENT 'Font Awesome icon class',
    title VARCHAR(150) NOT NULL COMMENT 'Judul fitur',
    description TEXT NOT NULL COMMENT 'Deskripsi fitur',
    link_url VARCHAR(255) DEFAULT '#' COMMENT 'Link detail fitur',
    link_text VARCHAR(100) DEFAULT 'Baca Selengkapnya' COMMENT 'Teks link',
    feature_order INT DEFAULT 0 COMMENT 'Urutan tampilan',
    delay_class VARCHAR(20) DEFAULT '' COMMENT 'CSS class untuk delay animasi',
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = nonaktif',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Fitur/keunggulan layanan';

