-- =====================================================
-- TABEL: packages
-- Fungsi: Paket Umrah dan Haji
-- =====================================================
CREATE TABLE IF NOT EXISTS packages (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(150) NOT NULL COMMENT 'Nama paket',
    price VARCHAR(50) NOT NULL COMMENT 'Harga paket (format: Rp 35.000.000)',
    currency VARCHAR(10) DEFAULT 'Rp' COMMENT 'Mata uang',
    duration VARCHAR(50) COMMENT 'Durasi paket (contoh: 9 Hari)',
    image_url VARCHAR(255) COMMENT 'URL gambar paket',
    tag VARCHAR(50) COMMENT 'Tag/label (contoh: Most Popular)',
    button_text VARCHAR(100) DEFAULT 'Pesan Sekarang' COMMENT 'Teks tombol CTA',
    button_link VARCHAR(255) DEFAULT '#contact' COMMENT 'Link tombol CTA',
    package_order INT DEFAULT 0 COMMENT 'Urutan tampilan',
    delay_class VARCHAR(20) DEFAULT '' COMMENT 'CSS class untuk delay animasi',
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = nonaktif',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Paket umrah dan haji';

