-- =====================================================
-- TABEL: admins
-- Fungsi: Akun admin untuk login panel admin
-- =====================================================
CREATE TABLE IF NOT EXISTS admins (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE COMMENT 'Username login',
    password VARCHAR(255) NOT NULL COMMENT 'Password (hashed)',
    full_name VARCHAR(100) COMMENT 'Nama lengkap',
    email VARCHAR(100) UNIQUE COMMENT 'Email admin',
    avatar VARCHAR(255) DEFAULT NULL COMMENT 'Foto profil admin',
    role ENUM('super_admin', 'admin', 'editor') DEFAULT 'admin' COMMENT 'Role admin',
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = nonaktif',
    remember_token VARCHAR(255) DEFAULT NULL COMMENT 'Token untuk remember me',
    token_expires TIMESTAMP NULL COMMENT 'Waktu expired token',
    last_login TIMESTAMP NULL COMMENT 'Waktu login terakhir',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Akun admin';

