-- =====================================================
-- TABEL: admin_logs
-- Fungsi: Log aktivitas admin
-- =====================================================
CREATE TABLE IF NOT EXISTS admin_logs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    admin_id INT NOT NULL COMMENT 'ID admin',
    action VARCHAR(100) NOT NULL COMMENT 'Aksi yang dilakukan',
    description TEXT COMMENT 'Deskripsi aksi',
    ip_address VARCHAR(45) COMMENT 'IP Address',
    user_agent TEXT COMMENT 'Browser/User Agent',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='Log aktivitas admin';

-- =====================================================
-- TABEL: page_sections
-- Fungsi: Section tambahan yang bisa dikustom (general purpose)
-- =====================================================
CREATE TABLE IF NOT EXISTS page_sections (
    id INT AUTO_INCREMENT PRIMARY KEY,
    page_name VARCHAR(100) NOT NULL COMMENT 'Nama halaman (home, about, dll)',
    section_name VARCHAR(100) NOT NULL COMMENT 'Nama section',
    section_title VARCHAR(255) COMMENT 'Judul section',
    section_subtitle VARCHAR(255) COMMENT 'Subtitle section',
    section_content TEXT COMMENT 'Konten section',
    section_image VARCHAR(255) COMMENT 'Gambar section',
    section_order INT DEFAULT 0 COMMENT 'Urutan tampilan',
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = nonaktif',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Section halaman yang bisa dikustom';

-- =====================================================
-- TABEL: subscribers
-- Fungsi: Daftar subscriber/newsletter
-- =====================================================
CREATE TABLE IF NOT EXISTS subscribers (
    id INT AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(100) NOT NULL UNIQUE COMMENT 'Email subscriber',
    name VARCHAR(100) COMMENT 'Nama subscriber',
    subscribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_active TINYINT(1) DEFAULT 1 COMMENT '1 = aktif, 0 = unsubscribe'
) ENGINE=InnoDB COMMENT='Daftar subscriber';

-- =====================================================
-- TABEL: inquiries
-- Fungsi: Form kontak/pertanyaan dari pengunjung
-- =====================================================
CREATE TABLE IF NOT EXISTS inquiries (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL COMMENT 'Nama pengirim',
    email VARCHAR(100) NOT NULL COMMENT 'Email pengirim',
    phone VARCHAR(20) COMMENT 'Nomor telepon',
    subject VARCHAR(255) COMMENT 'Subjek pesan',
    message TEXT NOT NULL COMMENT 'Isi pesan',
    package_interest INT COMMENT 'ID paket yang diminati (foreign key)',
    status ENUM('new', 'read', 'replied', 'closed') DEFAULT 'new' COMMENT 'Status pesan',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (package_interest) REFERENCES packages(id) ON DELETE SET NULL
) ENGINE=InnoDB COMMENT='Pertanyaan/kontak dari pengunjung';

-- =====================================================
-- TABEL: articles
-- Fungsi: Halaman artikel/konten dinamis
-- =====================================================
DROP TABLE IF EXISTS articles;
CREATE TABLE articles (
    id INT AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(100) NOT NULL UNIQUE COMMENT 'URL slug (contoh: akomodasi-premium)',
    title VARCHAR(200) NOT NULL COMMENT 'Judul artikel',
    title_highlight VARCHAR(100) COMMENT 'Bagian judul yang di-highlight (gold)',
    subtitle VARCHAR(255) COMMENT 'Subtitle di hero section',
    hero_image VARCHAR(500) COMMENT 'URL gambar hero background',
    content_image VARCHAR(500) COMMENT 'URL gambar di content section',
    content_title VARCHAR(200) COMMENT 'Judul konten utama',
    content_text TEXT COMMENT 'Teks paragraf utama',
    features_json TEXT COMMENT 'JSON array untuk list fitur [{icon, title, desc}]',
    cards_section_title VARCHAR(100) COMMENT 'Judul section kartu (opsional)',
    cards_section_subtitle VARCHAR(100) COMMENT 'Subtitle section kartu',
    cards_json TEXT COMMENT 'JSON array untuk kartu [{image, title, location, rating}]',
    cta_title VARCHAR(200) COMMENT 'Judul CTA section',
    cta_text VARCHAR(255) COMMENT 'Teks CTA section',
    meta_description VARCHAR(255) COMMENT 'Meta description untuk SEO',
    is_active TINYINT(1) DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Halaman artikel dinamis';

